      const d = { A: 0 }, done = {}; while (Object.keys(done).length < 5) { const u = V.filter(v => !done[v] && d[v] !== undefined).sort((x, y) => d[x] - d[y])[0]; if (!u) break; done[u] = 1; E.forEach(e => { [[e[0], e[1]], [e[1], e[0]]].forEach(([x, y]) => { if (x === u && (d[y] === undefined || d[u] + e[2] < d[y])) d[y] = d[u] + e[2]; }); }); }
      return [`Дороги между пунктами: ${E.map(e => `${e[0]}–${e[1]}: ${e[2]} км`).join("; ")}. Найдите длину кратчайшего пути из A в E.`, `${d.E} км`];
