      [r => { const k = pk(r, [3, 4]), n = ri(r, 10, 25), w = n % (k + 1) !== 0; return [`В куче ${n} камней. За ход можно взять от 1 до ${k} камней; выигрывает тот, кто берёт последний камень. Кто выигрывает при правильной игре? Каким должен быть первый ход, если первый игрок выигрывает?`, w ? `первый игрок; взять ${n % (k + 1)}` : "второй игрок"]; }],
      [r => { const k = pk(r, [3, 4]), n = (k + 1) * ri(r, 2, 5); return [`Куча из ${n} камней, ходы от 1 до ${k}. Докажите, что второй игрок всегда может выиграть, и опишите его стратегию.`, `ответ на ход первого — взять столько, чтобы за два хода было взято ${k + 1}; остаток всегда кратен ${k + 1}`]; }]
